import pyomo.environ as pyo

DATA = {
    "PACKAGES": ["X", "Y", "Z"],
    "cost": {"X": 500, "Y": 300, "Z": 700},
    "rating": {"X": 5, "Y": 3, "Z": 7},
    "total_tours_max": 50,
    "rating_min": 100,
    "diversity_gap": 10,
    "upper_bound": {"X": 50, "Y": 50, "Z": 50},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.PACKAGES = pyo.Set(initialize=d["PACKAGES"])

    def ub_rule(m, i):
        return (0, d["upper_bound"][i])

    model.x = pyo.Var(
        model.PACKAGES,
        domain=pyo.NonNegativeIntegers,
        bounds=ub_rule,
    )

    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.PACKAGES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_tours_rule(m):
        return sum(m.x[i] for i in m.PACKAGES) <= d["total_tours_max"]

    model.total_tours = pyo.Constraint(rule=total_tours_rule)

    def rating_rule(m):
        return sum(d["rating"][i] * m.x[i] for i in m.PACKAGES) >= d["rating_min"]

    model.rating = pyo.Constraint(rule=rating_rule)

    def diversity_rule(m):
        return m.x["X"] - m.x["Y"] >= d["diversity_gap"]

    model.diversity = pyo.Constraint(rule=diversity_rule)

    return model


